-- Fecha: 2026-10-14
-- Propósito: para los sitio-mes de la cohorte 2025 sin filas en el panel (cross_source/007 y 008) ni fila de
--            aurora (006, 007, 009) — 8333 en móvil y 5802 en escritorio, 1791 páginas —, saber si HTTP Archive
--            visitó la página ese mes. Para las visitas que existan, el rank permite traer aurora en otra
--            query sin leer la tabla completa (rank y page son columnas de clustering). Solo columnas
--            livianas (sin custom_metrics ni technologies).
-- Filtro de partición: date BETWEEN '2025-01-01' AND '2025-12-01' + is_root_page + lista literal de
--            1791 páginas (page es columna de clustering)
-- Tablas: httparchive.crawl.pages

SELECT
  date,
  client,
  page,
  rank
FROM `httparchive.crawl.pages`
WHERE date BETWEEN '2025-01-01' AND '2025-12-01'
